class GuardClauseDemo {

    // Cach viet cu: else long nhau, duong di chinh bi thut le sau dan.
    static String classifyNested(int score) {
        String result;
        if (score < 0) {
            result = "Invalid";
        } else {
            if (score < 50) {
                result = "Fail";
            } else {
                if (score < 80) {
                    result = "Pass";
                } else {
                    result = "Distinction";
                }
            }
        }
        return result;
    }

    // Guard clause: xu ly truong hop khong hop le truoc, return ngay;
    // phan con lai la duong di chinh, khong long else.
    static String classifyGuard(int score) {
        if (score < 0) {
            return "Invalid";
        }
        if (score < 50) {
            return "Fail";
        }
        if (score < 80) {
            return "Pass";
        }
        return "Distinction";
    }

    public static void main(String[] args) {
        int[] samples = {-5, 42, 65, 95};
        for (int score : samples) {
            System.out.println(score + " -> nested=" + classifyNested(score)
                    + ", guard=" + classifyGuard(score));
        }
    }
}

class SwitchClassicDemo {
    public static void main(String[] args) {
        int month = 3;
        String season;
        switch (month) {
            case 12:
            case 1:
            case 2:
                season = "Winter";
                break;
            case 3:
            case 4:
            case 5:
                season = "Spring";
                break;
            default:
                season = "Unknown";
        }
        System.out.println(season); // Spring
    }
}

class SwitchExpressionDemo {
    public static void main(String[] args) {
        int month = 3;
        String season = switch (month) {
            case 12, 1, 2 -> "Winter";
            case 3, 4, 5 -> "Spring";
            default -> {
                yield "Unknown";
            }
        };
        System.out.println(season); // Spring
    }
}

class PatternMatchingDemo {
    static String describe(Object value) {
        if (value instanceof String s) {
            return "String có độ dài " + s.length();
        } else if (value instanceof Integer i) {
            return "Integer gấp đôi là " + (i * 2);
        }
        return "Khong xac dinh";
    }

    public static void main(String[] args) {
        System.out.println(describe("java"));
        System.out.println(describe(21));
    }
}

class ForLoopDemo {
    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        int sum = 0;
        for (int i = 0; i < numbers.length; i++) {
            sum += numbers[i];
        }
        System.out.println("sum(for) = " + sum);

        int sumEnhanced = 0;
        for (int n : numbers) {
            sumEnhanced += n;
        }
        System.out.println("sum(enhanced for) = " + sumEnhanced);
    }
}

